css:
/* Homepage design system. This template wraps only the homepage, so these
   overrides restyle the homepage and nothing else; every rule below reads them. */
@font-face { font-family: "Aleo"; src: url("/fonts/aleo-latin-var.woff2") format("woff2"); font-weight: 100 900; font-display: swap; }
@font-face { font-family: "Mulish"; src: url("/fonts/mulish-latin-var.woff2") format("woff2"); font-weight: 200 1000; font-display: swap; }
:root {
  --accent: #0090e4;
  --accent-dark: #0a5aa3;
  --ink: #1b1b1b;
  --ink-dark: #000000;
  --muted: #5b6270;
  --line: #cfd5dd;
  --card: #ffffff;
  --paper: #f1f5f9;
  /* Brand fonts: Jubilat (headings) and Niveau Grotesk (body). Both are licensed, so the
     files are not in this repo yet: add @font-face rules for them above (files in
     public/fonts/) and they take over from the stand-ins below with no other change.
     Aleo and Mulish are the free stand-ins, and the sizes in this file were fitted to them. */
  --font-heading: "Jubilat", "Aleo", Georgia, serif;
  --font-body: "Niveau Grotesk", "Mulish", system-ui, sans-serif;
  --text-h1: 3rem;
  --text-h2: 1.75rem;
  --text-h3: 1.375rem;
  --text-body: 0.875rem;
  --text-small: 0.8125rem;
  --text-eyebrow: 0.6875rem;
  --weight-heading: 800;
  --leading-heading: 1.15;
  --leading-body: 1.6;
  --radius-card: 4px;
  --radius-input: 2px;
  --radius-nav: 0px;
  --container: calc(min(90vw, 1530px) + 32px);
  --ballard-navy: color-mix(in srgb, var(--accent-dark) 62%, #000);
  --ballard-sky: color-mix(in srgb, var(--accent) 9%, #fff);
  --ballard-link: color-mix(in srgb, var(--accent) 80%, #fff);
  --ballard-star: #f5b301;
}
body { font-family: var(--font-body); color: var(--ink); }
.bz-btn--primary { color: #fff; border-radius: var(--radius-input); }
.bz-btn--primary:hover { color: #fff; }

/* Utility bar */
[data-bz-node="hm-utility"] { background: var(--ink-dark); }
[data-bz-node="hm-utility"] .bz-block { padding-block: 6px; }
[data-bz-node="hm-utility"] .bz-nav { gap: var(--space-5); }
[data-bz-node="hm-utility"] .bz-navitem > a { font: 500 0.6875rem/1.2 var(--font-body); color: #fff; }
[data-bz-node="hm-utility"] .bz-navitem > a:hover { color: var(--ballard-link); }
[data-bz-node="hm-search"] .bz-widget { margin: 0; padding: 0; border: 0; background: none; }
[data-bz-node="hm-search"] .bz-searchbar { display: flex; gap: 0; max-width: 300px; margin-left: auto; padding: 0; background: none; border: 0; box-shadow: none; }
[data-bz-node="hm-search"] .bz-input { height: 26px; min-height: 0; padding: 0 8px; font: 400 0.6875rem/1 var(--font-body); border: 0; border-radius: 2px 0 0 2px; background: #fff; }
[data-bz-node="hm-search"] .bz-btn { height: 26px; min-height: 0; width: 30px; padding: 0; border-radius: 0 2px 2px 0; font-size: 0; position: relative; }
[data-bz-node="hm-search"] .bz-btn::before {
  content: ""; position: absolute; inset: 0; margin: auto; width: 13px; height: 13px; background: #fff;
  -webkit-mask: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27%23000%27 stroke-width=%273%27%3E%3Ccircle cx=%2710%27 cy=%2710%27 r=%276.5%27/%3E%3Cpath d=%27M15 15l6.5 6.5%27/%3E%3C/svg%3E") center / contain no-repeat;
          mask: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27%23000%27 stroke-width=%273%27%3E%3Ccircle cx=%2710%27 cy=%2710%27 r=%276.5%27/%3E%3Cpath d=%27M15 15l6.5 6.5%27/%3E%3C/svg%3E") center / contain no-repeat;
}
[data-bz-node="hm-search"] .bz-searchbar__chips { display: none; }

/* Header */
[data-bz-node="hm-header"] { background: #f5f8fb; border-bottom: 1px solid var(--line); }
[data-bz-node="hm-header"] .bz-block { padding-block: 10px; }
[data-bz-node="hm-logo"] .bz-logo__img { height: 54px; width: auto; }
[data-bz-node="hm-main-nav"] .bz-menu-wrap { display: flex; justify-content: flex-end; }
[data-bz-node="hm-main-nav"] .bz-nav { gap: 0 var(--space-5); flex-wrap: nowrap; }
[data-bz-node="hm-main-nav"] .bz-navitem > a { font: 500 0.8125rem/1.2 var(--font-body); color: var(--ink); padding-block: 18px; white-space: nowrap; }
[data-bz-node="hm-main-nav"] .bz-navitem > a:hover,
[data-bz-node="hm-main-nav"] .bz-navitem--has-sub:focus-within > a { color: var(--accent); }
[data-bz-node="hm-main-nav"] .bz-nav > .bz-navitem--has-sub > a::after { content: ""; display: inline-block; margin-left: 6px; vertical-align: 2px; border: 4px solid transparent; border-top: 5px solid currentColor; border-bottom: 0; }
[data-bz-node="hm-main-nav"] .bz-subnav { top: 100%; min-width: 13rem; padding: 6px 0; border: 0; border-top: 3px solid var(--accent); border-radius: 0; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18); }
[data-bz-node="hm-main-nav"] .bz-subnav .bz-navitem > a { display: block; padding: 9px 18px; font: 500 0.8125rem/1.2 var(--font-body); }
[data-bz-node="hm-main-nav"] .bz-subnav .bz-navitem > a:hover { background: var(--ballard-sky); color: var(--accent-dark); }
@media (max-width: 1100px) {
  [data-bz-node="hm-main-nav"] .bz-menu-wrap { justify-content: flex-end; display: flex; }
  [data-bz-node="hm-main-nav"] .bz-menu-toggle { color: var(--ink); }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] > .bz-menu { z-index: 40; box-shadow: 0 12px 24px rgba(0, 0, 0, 0.15); }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-nav { gap: 0; width: 100%; }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-navitem { width: 100%; border-bottom: 1px solid var(--line); }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-navitem > a { padding-block: 12px; }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-subnav { position: static; display: flex; box-shadow: none; border: 0; padding: 0 0 8px 16px; }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-subnav .bz-navitem { border: 0; }
  [data-bz-node="hm-main-nav"] .bz-menu-wrap[data-open] .bz-subnav .bz-navitem > a { padding: 6px 0; }
}

/* Hiring bar */
[data-bz-node="hm-hiring"] { background: var(--ink-dark); }
[data-bz-node="hm-hiring"] .bz-block { padding-block: 8px; }
[data-bz-node="hm-hiring"] .bz-text p { margin: 0; font: 500 0.6875rem/1.4 var(--font-body); color: #fff; }
[data-bz-node="hm-hiring"] .bz-text a { color: var(--ballard-link); text-decoration: none; }
[data-bz-node="hm-hiring"] .bz-text a:hover { text-decoration: underline; }

/* Footer. Measured from the reference footer (a 1920px window scaled to 1835px). */
[data-bz-node="hm-footer"] { background: #000; color: #fff; padding-block: 63px 8px; }
[data-bz-node="hm-footer"] > .bz-container { max-width: calc(min(90vw, 1504px) + 32px); }
[data-bz-node="hm-footer"] .bz-block { padding-block: 0; }
@media (min-width: 1101px) {
  [data-bz-node="hm-footer-row"] { grid-template-columns: 695fr 380fr 430fr; gap: 0; }
  [data-bz-node="hm-footer-row"] > .bz-col { grid-column: auto; }
}
[data-bz-node="hm-footer-logo"] .bz-logo__img { height: 53px; width: auto; }
[data-bz-node="hm-footer"] h2 { font: 900 1.33rem / 1.2 var(--font-heading); color: #fff; margin: 0; }
[data-bz-node="hm-footer-tagline"] h2 { font-size: 1.38rem; font-style: italic; margin-top: 56px; }
[data-bz-node="hm-footer-blurb"] { margin-top: 16px; }
[data-bz-node="hm-footer"] .bz-text p { font: 500 0.906rem / 1.52 var(--font-body); color: #fff; margin: 0; max-width: 600px; }
[data-bz-node="hm-footer-awards"] { margin-top: 37px; }
[data-bz-node="hm-footer-awards"] .bz-logos { display: flex; flex-wrap: wrap; justify-content: flex-start; align-items: center; gap: 24px 47px; border: 0; padding: 0; }
[data-bz-node="hm-footer-awards"] .bz-logo img { display: block; width: auto; max-width: 100%; height: auto; }
[data-bz-node="hm-footer-connect-h"] { padding-top: 0; }
[data-bz-node="hm-footer-news-form"] .bz-formblock > h2 { font-size: 1.36rem; }
[data-bz-node="hm-footer-connect-nav"] { margin-top: 13px; }
[data-bz-node="hm-footer-connect"], [data-bz-node="hm-footer-news"] { padding-top: 32px; }
@media (min-width: 1101px) { [data-bz-node="hm-footer-connect"] { padding-top: 114px; } [data-bz-node="hm-footer-news"] { padding-top: 118px; } }
[data-bz-node="hm-footer-connect-nav"] .bz-nav { gap: 14px; }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem > a { display: flex; align-items: center; min-height: 30px; padding: 0 0 0 38px; position: relative; font: 500 0.906rem / 1.2 var(--font-body); color: #fff; }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem > a:hover { color: var(--ballard-link); }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem > a::before { content: ""; position: absolute; left: 0; top: 50%; width: 21px; height: 21px; margin-top: -10.5px; background: var(--accent); -webkit-mask: var(--ico) center / 100% 100% no-repeat; mask: var(--ico) center / 100% 100% no-repeat; }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem:nth-child(1) > a { --ico: url("/footer/phone.svg"); }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem:nth-child(2) > a { --ico: url("/footer/send.svg"); }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem:nth-child(3) > a { --ico: url("/footer/briefcase.svg"); }
[data-bz-node="hm-footer-connect-nav"] .bz-navitem:nth-child(4) > a { --ico: url("/footer/list.svg"); }
[data-bz-node="hm-footer-news-form"] .bz-formblock { max-width: none; }
[data-bz-node="hm-footer-news-form"] .bz-form { background: none; border: 0; padding: 0; margin-top: 12px; max-width: none; gap: 0; }
[data-bz-node="hm-footer-news-form"] .bz-form__t,
[data-bz-node="hm-footer-news-form"] [data-bz-field="nl-lists"] > .bz-label,
[data-bz-node="hm-footer-news-form"] [data-bz-field="nl-lists"] > legend,
[data-bz-node="hm-footer-news-form"] [data-bz-field="nl-email"] .bz-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
[data-bz-node="hm-footer-news-form"] .bz-choices { display: flex; flex-direction: column; gap: 0; }
[data-bz-node="hm-footer-news-form"] .bz-choice { display: flex; align-items: center; gap: 9px; min-height: 20px; color: #fff; font: 500 0.894rem / 1.2 var(--font-body); }
[data-bz-node="hm-footer-news-form"] .bz-choice input { -webkit-appearance: none; appearance: none; flex: 0 0 auto; width: 12.5px; height: 12.5px; margin: 0; border-radius: 50%; background: #fafafa; }
[data-bz-node="hm-footer-news-form"] .bz-choice input:checked { background: var(--accent); box-shadow: inset 0 0 0 2.5px #000; outline: 1.5px solid var(--accent); }
[data-bz-node="hm-footer-news-form"] [data-bz-field="nl-email"] { margin-top: 15px; }
[data-bz-node="hm-footer-news-form"] .bz-input { height: 39px; min-height: 0; padding: 0 11px; border: 0; border-radius: 3px; background: #ebf8ff; color: #26395d; font: 500 0.875rem / 1 var(--font-body); }
[data-bz-node="hm-footer-news-form"] .bz-input::placeholder { color: #26395d; opacity: 1; }
[data-bz-node="hm-footer-news-form"] .bz-form > .bz-btn { flex: 0 0 auto; width: auto; height: 43px; margin-top: 22px; padding: 0 24px; border-radius: 0; font: 800 1rem / 1 var(--font-body); }
[data-bz-node="hm-footer-social-row"] { margin-top: 46px; }
[data-bz-node="hm-footer-social"] .bz-nav { gap: 0; }
[data-bz-node="hm-footer-social"] .bz-navitem { width: 41px; display: flex; justify-content: center; }
[data-bz-node="hm-footer-social"] .bz-navitem > a,
[data-bz-node="hm-footer-social"] .bz-navlabel { display: block; padding: 0; font-size: 0; width: var(--iw); height: var(--ih); background: #fff; -webkit-mask: var(--ico) center / 100% 100% no-repeat; mask: var(--ico) center / 100% 100% no-repeat; }
[data-bz-node="hm-footer-social"] .bz-navitem > a:hover { background: var(--ballard-link); }
[data-bz-node="hm-footer-social"] .bz-navitem:nth-child(1) { --ico: url("/footer/facebook.svg"); --iw: 14.6px; --ih: 23px; }
[data-bz-node="hm-footer-social"] .bz-navitem:nth-child(2) { --ico: url("/footer/instagram.svg"); --iw: 21px; --ih: 20px; }
[data-bz-node="hm-footer-social"] .bz-navitem:nth-child(3) { --ico: url("/footer/linkedin.svg"); --iw: 22px; --ih: 20px; }
[data-bz-node="hm-footer-social"] .bz-navitem:nth-child(4) { --ico: url("/footer/youtube.svg"); --iw: 25px; --ih: 18px; }
[data-bz-node="hm-footer-social"] .bz-navitem:nth-child(5) { --ico: url("/footer/tiktok.svg"); --iw: 21px; --ih: 23px; }
[data-bz-node="hm-footer-legal-row"] { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 4px 3px; margin-top: 23px; padding-top: 0; border-top: 0; }
[data-bz-node="hm-footer-legal-row"] > .bz-col { flex: 0 0 auto; width: auto; }
[data-bz-node="hm-footer-legal-row"] .bz-block { padding: 0; }
[data-bz-node="hm-footer-copy"] .bz-text p { font: 500 0.893rem / 1.4 var(--font-body); color: #fff; max-width: none; }
[data-bz-node="hm-footer-legal"] .bz-nav { gap: 0; }
[data-bz-node="hm-footer-legal"] .bz-navitem + .bz-navitem::before { content: "|"; color: #fff; padding: 0 4px; font-size: 0.893rem; }
[data-bz-node="hm-footer-legal"] .bz-navitem > a { font: 500 0.893rem / 1.4 var(--font-body); color: #0089db; padding: 0; }

@media (max-width: 640px) {
  [data-bz-node="hm-utility-row"] > .bz-col { grid-column: 1 / -1; }
  [data-bz-node="hm-utility-links"] .bz-menu { justify-content: center; }
  [data-bz-node="hm-search"] .bz-searchbar { max-width: none; margin: 0 0 4px; }
  [data-bz-node="hm-logo"] .bz-logo__img { height: 44px; }
  [data-bz-node="hm-header-brand"] { grid-column: span 8; }
  [data-bz-node="hm-header-nav"] { grid-column: span 4; }
  [data-bz-node="hm-footer"] { padding-block: 44px 16px; }
  [data-bz-node="hm-footer-tagline"] h2 { margin-top: 28px; }
  [data-bz-node="hm-footer-awards"] .bz-logos { gap: 20px 28px; }
  [data-bz-node="hm-footer-legal-row"] { justify-content: center; text-align: center; }
}
